const bidModal=document.getElementById('bidModal');
const publishOverlay=document.createElement('div');publishOverlay.className='job-publish-overlay';publishOverlay.hidden=true;publishOverlay.innerHTML='<div class="job-publish-card"><div class="build-animation"><div class="build-crane"></div><div class="build-frame"></div><div class="build-ground"></div></div><div class="job-publish-check">&#10003;</div><span class="kicker">Contractor marketplace</span><h2 id="publishOverlayTitle">Publishing your job...</h2><p id="publishOverlayMessage">Building the listing and notifying matching subcontractors.</p><div class="job-publish-actions" hidden><button class="button button-dark" type="button" id="closePublishOverlay">Close</button></div></div>';document.body.appendChild(publishOverlay);document.getElementById('closePublishOverlay').onclick=()=>publishOverlay.hidden=true;
const delay=milliseconds=>new Promise(resolve=>setTimeout(resolve,milliseconds));function showPublishProgress(){const card=publishOverlay.querySelector('.job-publish-card');card.className='job-publish-card';document.getElementById('publishOverlayTitle').textContent='Publishing your job...';document.getElementById('publishOverlayMessage').textContent='Building the listing and notifying matching subcontractors.';publishOverlay.querySelector('.job-publish-actions').hidden=true;publishOverlay.hidden=false}function showPublishSuccess(job){const card=publishOverlay.querySelector('.job-publish-card');card.className='job-publish-card success';document.getElementById('publishOverlayTitle').textContent='Job posted successfully';document.getElementById('publishOverlayMessage').textContent=`${job.title} is now live in ${job.city}, ${job.state}. Matching subcontractors can view and bid on it.`}function showPublishError(message){const card=publishOverlay.querySelector('.job-publish-card');card.className='job-publish-card error';publishOverlay.querySelector('.job-publish-check').textContent='!';document.getElementById('publishOverlayTitle').textContent='Job was not posted';document.getElementById('publishOverlayMessage').textContent=message;publishOverlay.querySelector('.job-publish-actions').hidden=false}
function applyJobRoleExperience(){if(!dashboard)return;const company=dashboard.company,isContractor=company.capabilities.includes('contractor'),isSub=company.capabilities.includes('subcontractor'),subOnly=isSub&&!isContractor,postForm=document.getElementById('jobPostForm'),jobsNav=document.querySelector('[data-view="jobs"]'),primaryAction=document.getElementById('primaryAction'),roleBadge=document.getElementById('navRole'),jobFilters=document.getElementById('jobFilters'),availableSection=document.getElementById('availableJobGrid').closest('.job-section');roleBadge.textContent=isContractor&&isSub?'Contractor & Subcontractor':isContractor?'Contractor':'Subcontractor';postForm.hidden=!isContractor;postForm.querySelectorAll('input,textarea,button,select').forEach(field=>field.disabled=!isContractor);document.getElementById('postedJobsSection').hidden=!isContractor;jobFilters.hidden=!isSub;availableSection.hidden=!isSub;if(isSub&&jobFilters.previousElementSibling!==availableSection.querySelector('.card-heading'))availableSection.querySelector('.card-heading').after(jobFilters);if(subOnly){jobsNav.childNodes[0].textContent='Find Jobs ';primaryAction.textContent='Find nearby jobs';primaryAction.onclick=()=>switchView('jobs')}else if(isContractor&&!isSub){jobsNav.childNodes[0].textContent='Manage Jobs ';primaryAction.textContent='Build your network';primaryAction.onclick=()=>switchView('network')}else{jobsNav.childNodes[0].textContent='Jobs ';primaryAction.textContent='Open job marketplace';primaryAction.onclick=()=>switchView('jobs')}}
function renderJobMarketplace(){if(!dashboard)return;applyJobRoleExperience();const company=dashboard.company,isContractor=company.capabilities.includes('contractor'),isSub=company.capabilities.includes('subcontractor');document.getElementById('jobsHeading').textContent=isSub&&!isContractor?'Available jobs in your market':isSub?'Find jobs and manage postings':'Post and manage jobs';document.getElementById('jobsIntro').textContent=isSub?'Browse every open contractor-posted job within your service area, message the contractor, and submit private bids.':'Publish scopes and privately review bids from subcontractors.';document.getElementById('jobsCount').textContent=isSub?dashboard.availableJobs.length:dashboard.postedJobs.length;const city=document.getElementById('jobCityFilter').value.trim().toLowerCase(),state=document.getElementById('jobStateFilter').value.trim().toLowerCase(),trade=document.getElementById('jobTradeFilter').value.trim().toLowerCase(),jobs=dashboard.availableJobs.filter(job=>(!city||job.city.toLowerCase().includes(city))&&(!state||job.state.toLowerCase()===state)&&(!trade||job.trade.toLowerCase().includes(trade)));document.getElementById('availableJobGrid').innerHTML=isSub?(jobs.length?jobs.map(jobCard).join(''):'<div class="list-empty">No open jobs match those filters in your service area yet.</div>'):'<div class="list-empty">Enable subcontractor capability to browse and bid on marketplace jobs.</div>';document.getElementById('postedJobGrid').innerHTML=dashboard.postedJobs.length?dashboard.postedJobs.map(postedJobCard).join(''):'<div class="list-empty">You have not posted a job yet.</div>';document.querySelectorAll('[data-bid-job]').forEach(button=>button.addEventListener('click',()=>openBid(button.dataset.bidJob)));document.querySelectorAll('[data-message-job]').forEach(button=>button.addEventListener('click',()=>messageJob(button.dataset.messageJob,button.dataset.company)));document.querySelectorAll('[data-review-bids]').forEach(button=>button.addEventListener('click',()=>reviewBids(button.dataset.reviewBids)));document.querySelectorAll('[data-edit-job]').forEach(button=>button.addEventListener('click',()=>openEditJob(button.dataset.editJob)));document.querySelectorAll('[data-delete-job]').forEach(button=>button.addEventListener('click',()=>confirmDeleteJob(button.dataset.deleteJob)))}
function fmtBudget(raw){if(!raw)return'Open';const n=parseFloat(String(raw).replace(/[^0-9.]/g,''));return Number.isFinite(n)?new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n):raw}
function fmtJobDate(raw){if(!raw)return'Flexible';const match=String(raw).match(/^(\d{4})-(\d{2})-(\d{2})$/);if(!match)return raw;return new Date(Number(match[1]),Number(match[2])-1,Number(match[3])).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}
function bidCountHtml(count){return`<div class="market-job-bids"><strong class="${count>0?'bids-active':''}">${count}</strong><small>Bids</small></div>`}
function jobCard(job){return`<article class="market-job"><div class="job-topline"><span class="trade-pill">${escapeHtml(job.trade)}</span><span class="job-age">${job.city}, ${job.state}${Number.isFinite(job.distanceMiles)?` · ${job.distanceMiles} mi`:''}</span></div><h3>${escapeHtml(job.title)}</h3><p>${escapeHtml(job.description||'Contact the contractor for detailed scope information.')}</p><div class="market-job-meta"><span><strong>${escapeHtml(fmtBudget(job.budget))}</strong>Budget</span><span><strong>${escapeHtml(fmtJobDate(job.startDate))}</strong>Start</span>${bidCountHtml(job.bidCount)}</div><div class="job-company"><span class="company-mark">${initials(job.postingCompany.name)}</span><div><strong>${escapeHtml(job.postingCompany.name)}</strong><small>${escapeHtml(job.projectType||'Construction project')}</small></div></div><div class="market-job-actions"><button class="button button-orange" type="button" data-bid-job="${job.id}">${job.myBid?'Update bid':'Submit bid'}</button><button class="text-link" type="button" data-message-job="${job.id}" data-company="${job.postingCompany.id}">Message contractor</button></div>${job.myBid?`<small class="connection-status accepted">Your bid: ${escapeHtml(job.myBid.amount)}</small>`:''}</article>`}
function postedJobCard(job){const canEdit=job.status==='published';return`<article class="market-job"><div class="job-topline"><span class="trade-pill">${escapeHtml(job.trade)}</span><span class="connection-status accepted">${escapeHtml(job.status)}</span></div><h3>${escapeHtml(job.title)}</h3><p>${escapeHtml(job.description||'No scope summary')}</p><div class="market-job-meta"><span><strong>${escapeHtml(job.city)}, ${escapeHtml(job.state)}</strong>Location</span><span><strong>${escapeHtml(fmtBudget(job.budget))}</strong>Budget</span>${bidCountHtml(job.bidCount)}</div><div class="market-job-actions"><button class="button button-outline" type="button" data-review-bids="${job.id}">${job.status==='awarded'?'View awarded bid':'Review private bids'}</button>${canEdit?`<button class="text-link" type="button" data-edit-job="${job.id}">Edit</button><button class="text-link danger-link" type="button" data-delete-job="${job.id}">Delete</button>`:''}</div></article>`}
function openBid(jobId){if(!dashboard.company.capabilities.includes('subcontractor'))return showNotice('Enable subcontractor capability to submit bids.',true);const job=dashboard.availableJobs.find(item=>item.id===jobId);document.getElementById('bidJobTitle').textContent=job.title;const form=document.getElementById('bidForm');form.elements.jobId.value=job.id;form.elements.amount.value=job.myBid?.amount||'';form.elements.schedule.value=job.myBid?.schedule||'';form.elements.scope.value=job.myBid?.scope||'';bidModal.showModal()}
document.getElementById('closeBidModal').addEventListener('click',()=>bidModal.close());document.getElementById('bidForm').addEventListener('submit',async event=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.currentTarget)),jobId=data.jobId;delete data.jobId;try{await api(`/api/jobs/${jobId}/bids`,{method:'POST',body:JSON.stringify(data)});bidModal.close();await refresh();renderJobMarketplace();showNotice('Private bid submitted to the contractor.')}catch(error){showNotice(error.message,true)}});
document.getElementById('jobPostForm').addEventListener('submit',async event=>{event.preventDefault();if(!dashboard.company.capabilities.includes('contractor'))return showNotice('Only contractor-capable companies can post jobs.',true);const form=event.currentTarget,button=form.querySelector('[type="submit"]'),originalLabel=button.textContent;button.disabled=true;button.textContent='Publishing...';showPublishProgress();try{const[result]=await Promise.all([api('/api/jobs',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))}),delay(1600)]);form.reset();form.dataset.locationReady='';await refresh();renderJobMarketplace();showPublishSuccess(result.job);await delay(2200);publishOverlay.hidden=true;showNotice('Job published to the marketplace.')}catch(error){showPublishError(error.message)}finally{button.disabled=false;button.textContent=originalLabel}});
async function messageJob(jobId,companyId){try{const result=await api('/api/conversations',{method:'POST',body:JSON.stringify({companyId,jobId})});await refresh();switchView('messages');await openConversation(result.conversation.id)}catch(error){showNotice(error.message,true)}}
const bidReviewModal=document.createElement('dialog');bidReviewModal.className='modal bid-review-modal';bidReviewModal.innerHTML='<button class="modal-close" type="button" id="closeBidReviewModal">&times;</button><div class="modal-heading"><span class="kicker">Private bids</span><h2 id="bidReviewModalTitle">Review bids</h2></div><div id="bidReviewModalGrid" class="bid-grid"></div>';document.body.appendChild(bidReviewModal);document.getElementById('closeBidReviewModal').addEventListener('click',()=>bidReviewModal.close());
async function reviewBids(jobId){try{const result=await api(`/api/jobs/${jobId}/bids`);document.getElementById('bidReviewModalTitle').textContent=`Bids for ${result.job.title}`;document.getElementById('bidReviewModalGrid').innerHTML=result.bids.length?result.bids.map(bid=>`<article class="bid-card"><span class="trade-pill">${escapeHtml(bid.amount)}</span><h3>${escapeHtml(bid.biddingCompany.name)}</h3><p>${escapeHtml(bid.scope)}</p><small>${escapeHtml(bid.schedule||'Schedule not provided')}</small><div class="market-job-actions">${result.job.status==='published'?`<button class="button button-orange" type="button" data-award-bid="${bid.id}" data-award-job="${result.job.id}" data-award-company="${escapeHtml(bid.biddingCompany.name)}">Award & schedule</button>`:bid.status==='accepted'?'<span class="connection-status accepted">Awarded</span>':''}<button class="text-link" type="button" data-message-bid="${bid.biddingCompany.id}">Message bidder</button></div></article>`).join(''):'<div class="list-empty">No bids submitted yet.</div>';bidReviewModal.querySelectorAll('[data-message-bid]').forEach(button=>button.addEventListener('click',()=>startConversation(button.dataset.messageBid)));bidReviewModal.querySelectorAll('[data-award-bid]').forEach(button=>button.addEventListener('click',()=>window.openAwardSchedule(button.dataset.awardJob,button.dataset.awardBid,button.dataset.awardCompany)));bidReviewModal.showModal()}catch(error){showNotice(error.message,true)}}
['jobTradeFilter','jobCityFilter','jobStateFilter'].forEach(id=>document.getElementById(id).addEventListener('input',renderJobMarketplace));document.getElementById('clearJobFilters').addEventListener('click',()=>{['jobTradeFilter','jobCityFilter','jobStateFilter'].forEach(id=>document.getElementById(id).value='');renderJobMarketplace()});document.querySelector('[data-view="jobs"]').addEventListener('click',renderJobMarketplace);const originalRefresh=refresh;refresh=async function(){await originalRefresh();renderJobMarketplace()};
const editJobModal=document.createElement('dialog');editJobModal.className='modal';editJobModal.innerHTML='<form id="editJobForm" class="workspace-card" style="margin:0"><span class="kicker">Edit job</span><h3 id="editJobModalTitle"></h3><label><span>Job title</span><input name="title" required maxlength="180"></label><div class="form-row"><label><span>City</span><input name="city" required maxlength="80"></label><label><span>State</span><input name="state" required maxlength="2"></label></div><div class="form-row"><label><span>Budget</span><input name="budget" maxlength="100" placeholder="$30,000"></label><label><span>Start date</span><input name="startDate" type="date"></label></div><label><span>Description</span><textarea name="description" rows="4" maxlength="3000"></textarea></label><input type="hidden" name="jobId"><input type="hidden" name="placeId"><input type="hidden" name="formattedLocation"><input type="hidden" name="postalCode"><input type="hidden" name="latitude"><input type="hidden" name="longitude"><div style="display:flex;gap:12px;margin-top:8px"><button class="button button-orange" type="submit">Save changes</button><button class="button button-outline" type="button" id="closeEditJobModal">Cancel</button></div></form>';document.body.appendChild(editJobModal);document.getElementById('closeEditJobModal').addEventListener('click',()=>editJobModal.close());document.getElementById('editJobForm').addEventListener('submit',async event=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.currentTarget)),jobId=data.jobId;delete data.jobId;const button=event.currentTarget.querySelector('[type="submit"]');button.disabled=true;button.textContent='Saving...';try{await api(`/api/jobs/${jobId}`,{method:'PATCH',body:JSON.stringify(data)});editJobModal.close();await refresh();renderJobMarketplace();showNotice('Job updated.')}catch(error){showNotice(error.message,true)}finally{button.disabled=false;button.textContent='Save changes'}});
function openEditJob(jobId){const job=dashboard.postedJobs.find(item=>item.id===jobId);if(!job)return;document.getElementById('editJobModalTitle').textContent=job.title;const form=document.getElementById('editJobForm');form.elements.jobId.value=job.id;form.elements.title.value=job.title;form.elements.city.value=job.city;form.elements.state.value=job.state;window.TradesTaxonomy?.setLocationMetadata(form.elements.city,job);form.elements.budget.value=job.budget||'';form.elements.startDate.value=job.startDate||'';form.elements.description.value=job.description||'';editJobModal.showModal()}
async function confirmDeleteJob(jobId){const job=dashboard.postedJobs.find(item=>item.id===jobId);if(!job)return;if(!confirm(`Delete "${job.title}"? This cannot be undone.`))return;try{await api(`/api/jobs/${jobId}`,{method:'DELETE'});await refresh();renderJobMarketplace();showNotice('Job deleted.')}catch(error){showNotice(error.message,true)}}
const roleExperienceWait=setInterval(()=>{if(!dashboard)return;clearInterval(roleExperienceWait);renderJobMarketplace();if(dashboard.company.capabilities.includes('subcontractor')&&!dashboard.company.capabilities.includes('contractor')&&location.pathname==='/dashboard')switchView('jobs')},100);setTimeout(()=>clearInterval(roleExperienceWait),10000);
